function rob(nums: number[]): number {
  // prev2 — лучший результат для домов до i-2 включительно
  // prev1 — лучший результат для домов до i-1 включительно
  let prev2 = 0;
  let prev1 = 0;

  for (const money of nums) {
    // Либо пропускаем текущий дом (prev1),
    // либо грабим его и добавляем лучший результат без соседа (prev2 + money)
    const cur = Math.max(prev1, prev2 + money);

    // Сдвигаем «окно» из двух последних значений
    prev2 = prev1;
    prev1 = cur;
  }

  // prev1 — ответ для всех домов
  return prev1;
}

// Время: O(n) — один проход
// Память: O(1) — храним только два последних значения dp
